(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20+Math.cos(y*0.013-t*0.22)*15;
  const w1y = Math.cos(y*0.017-t*0.28)*20+Math.sin(x*0.015+t*0.33)*15;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*12+Math.cos((y+w1y)*0.01+t*0.18)*8;
  const w2y = Math.cos((y+w1y)*0.011+t*0.2)*12+Math.sin((x+w1x)*0.014-t*0.16)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.5],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.6],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.3],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.55],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.45],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.13,1.8,0.65]
  ];
  let aS=0,iS=0,iS2=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    iS2+=Math.sin(d*f*0.5-t*sp*0.3+3.0+ph*2);
  }
  const act=aS/8,inh=iS/8,inh2=iS2/8;
  let bg=0,amp=0.5,freq=0.04;
  for(let i=0;i<4;i++){
    bg+=amp*Math.sin(sx*freq+sy*freq*0.7+t*(0.8+i*0.3));
    bg+=amp*Math.cos(sx*freq*0.8-sy*freq+t*(0.6+i*0.2)+i);
    freq*=2.1;amp*=0.5;
  }
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*5+t*0.8))*0.33;
  const cellX=sx*0.08,cellY=sy*0.08;
  const ci=Math.floor(cellX),cj=Math.floor(cellY);
  const cf=cellX-ci,cg=cellY-cj;
  let minD=2,minD2=2;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const ni=ci+di,nj=cj+dj;
    const hx=Math.sin(ni*127.1+nj*311.7+t*0.4)*0.5+0.5;
    const hy=Math.cos(ni*269.5+nj*183.3+t*0.3)*0.5+0.5;
    const dx=di+hx-cf,dy=dj+hy-cg,d=Math.sqrt(dx*dx+dy*dy);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2)minD2=d;
  }
  const voronoi=minD2-minD;
  const pulse=Math.sin(dist*0.1-t*3)*Math.exp(-dist*0.005)*0.3;
  const reaction=Math.tanh((act-inh*0.6-inh2*0.3+bg*0.25+spiral*0.4+voronoi*0.3)*2.0);
  const blend=reaction*0.65+voronoi*0.15+pulse*0.1+spiral*0.1;
  const v=Math.tanh(blend)*0.5+0.5;
  const pal=[[5,12,55],[12,45,95],[18,85,120],[25,140,135],[60,180,130],[180,200,80],[220,170,60],[215,110,65],[180,60,75],[120,30,65],[60,15,50],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.2:(Math.abs(voronoi-0.15)<0.03?1.1:1.0);
  const glow=Math.max(0,1-dist*0.003)*0.1;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*20)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0
  ];
}
